"""Parse reaction strings into a stoichiometry matrix and rate vector.

Grammar (whitespace-insensitive)::

    reaction  := side "->" side "@" float
    side      := term ("+" term)*
    term      := coefficient? species        # default coefficient 1

Examples::

    A + B -> C @ 0.01
    C -> A + B @ 0.1
    2 H2O -> 2 H2 + O2 @ 3.5e-2
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field


class ParseError(ValueError):
    """Raised when a reaction string cannot be parsed."""


_ARROW_RE = re.compile(r"(->|=>|→|⟶)")
_RATE_RE = re.compile(r"^@?\s*([+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?)$")
_TERM_RE = re.compile(r"^(?:(\d+(?:\.\d+)?)\s*\*?\s*)?([A-Za-z][A-Za-z0-9_\[\]\-]*)$")


@dataclass(frozen=True)
class Reaction:
    """One elementary reaction with its mass-action rate constant."""

    reactants: dict[str, float] = field(default_factory=dict)
    products: dict[str, float] = field(default_factory=dict)
    rate: float = 1.0
    raw: str = ""

    def __str__(self) -> str:  # pragma: no cover - cosmetic
        def fmt(side: dict[str, float]) -> str:
            return " + ".join(
                f"{c:g} {s}" if c != 1 else s for s, c in side.items()
            )

        return f"{fmt(self.reactants)} -> {fmt(self.products)} @ {self.rate:g}"


def _parse_side(text: str, raw: str) -> dict[str, float]:
    side: dict[str, float] = {}
    for term in text.split("+"):
        term = term.strip()
        if not term:
            raise ParseError(f"empty reactant/product term in {raw!r}")
        m = _TERM_RE.match(term)
        if not m:
            raise ParseError(f"cannot parse term {term!r} in {raw!r}")
        coeff = float(m.group(1)) if m.group(1) is not None else 1.0
        species = m.group(2)
        side[species] = side.get(species, 0.0) + coeff
    return side


def parse_reaction(s: str) -> Reaction:
    """Parse a single reaction string into a :class:`Reaction`."""
    raw = s.strip()
    parts = _ARROW_RE.split(raw)
    if len(parts) != 3:
        raise ParseError(f"expected exactly one arrow '->' in {s!r}")
    lhs, rhs_with_rate, _ = parts

    # Split off the "@ rate" clause on the product side (or allow it anywhere).
    rate = 1.0
    for chunk in (lhs, rhs_with_rate):
        if "@" in chunk:
            if "@" in lhs and "@" in rhs_with_rate:
                raise ParseError(f"multiple '@rate' clauses in {s!r}")
            body, _, tail = chunk.partition("@")
            m = _RATE_RE.match(tail.strip())
            if not m:
                raise ParseError(f"cannot parse rate {tail!r} in {s!r}")
            rate = float(m.group(1))
            if chunk is lhs:
                lhs = body
            else:
                rhs_with_rate = body

    reactants = _parse_side(lhs, raw)
    products = _parse_side(rhs_with_rate, raw)
    return Reaction(reactants=reactants, products=products, rate=rate, raw=raw)


@dataclass(frozen=True)
class ReactionNetwork:
    """A set of reactions over a common species list.

    Attributes:
        species: ordered list of species names (row order of S).
        reactions: ordered list of :class:`Reaction` (column order of S).
    """

    reactions: tuple[Reaction, ...]
    species: tuple[str, ...]

    @property
    def stoichiometry_matrix(self):
        """S with shape ``(n_species, n_reactions)``; S[i, j] = d n_i / d xi_j."""
        import numpy as np

        idx = {s: i for i, s in enumerate(self.species)}
        S = np.zeros((len(self.species), len(self.reactions)))
        for j, rxn in enumerate(self.reactions):
            for sp, c in rxn.products.items():
                S[idx[sp], j] += c
            for sp, c in rxn.reactants.items():
                S[idx[sp], j] -= c
        return S

    @property
    def rate_vector(self):
        """Column vector of rate constants k = (k_1, ..., k_M)."""
        import numpy as np

        return np.array([r.rate for r in self.reactions], dtype=float)

    def index(self, species: str) -> int:
        return self.species.index(species)


def parse_network(reaction_strings) -> ReactionNetwork:
    """Parse an iterable of reaction strings into a network.

    Species are collected across all reactions and sorted alphabetically so
    that rows of the stoichiometry matrix have a deterministic order.
    """
    reactions = tuple(parse_reaction(s) for s in reaction_strings)
    species: set[str] = set()
    for r in reactions:
        species.update(r.reactants)
        species.update(r.products)
    return ReactionNetwork(
        reactions=reactions, species=tuple(sorted(species))
    )

